  precios_menores: p.precios_menores, incluye: p.incluye, no_incluye: p.no_incluye,
  condiciones: p.condiciones, descripcion: p.descripcion
});

const promoAnuncio = adId ? promos.find(p => (p.ad_ids || []).map(String).includes(adId)) : null;
// Las promos de prueba (id "prueba-...") solo se muestran a quien llega por su anuncio
const otras = promos.filter(p => !String(p.id).startsWith('prueba-') && (!promoAnuncio || p.id !== promoAnuncio.id));

return [{ json: {
  es_primer_mensaje: esPrimerMensaje,
  ad_id: adId,
  promo_id: promoAnuncio ? promoAnuncio.id : '',
  promo_anuncio: promoAnuncio ? JSON.stringify(resumir(promoAnuncio)) : 'ninguna',
  otras_promos: otras.length ? JSON.stringify(otras.map(resumir)) : 'ninguna'
} }];

// Texto y notas de voz que mandó el cliente desde la última respuesta nuestra.
// El texto viene del buffer (ráfaga); si la llamada llegó sin texto se lee de la conversación de GHL.
const buffer = String($('Buffer ¿es el último?').first().json.mensajes || '').trim();
let mensajes = [];
try { mensajes = $('GHL mensajes (texto)').first().json.messages?.messages || []; } catch (e) {}
const AUDIO = /\.(ogg|oga|opus|mp3|m4a|aac|wav|webm|amr|mpeg|mpga)(\?|$)/i;
const NO_AUDIO = /\.(jpe?g|png|gif|webp|heic|pdf|docx?|xlsx?|pptx?|txt|mp4|mov|3gp|avi)(\?|$)/i;
// GHL los devuelve del más nuevo al más viejo: tomamos los entrantes hasta la última respuesta nuestra
const textos = [], audios = [];
for (const m of mensajes) {
  if (String(m.messageType || '').startsWith('TYPE_ACTIVITY')) continue;
  if (m.direction === 'outbound') break;
  if (m.body) textos.unshift(String(m.body).trim());
  const tipo = String(m.contentType || m.meta?.contentType || '').toLowerCase();
  for (const url of (m.attachments || [])) {
    if (typeof url !== 'string' || !/^https?:/.test(url)) continue;
    if (AUDIO.test(url) || tipo.startsWith('audio') || (!NO_AUDIO.test(url) && !m.body)) audios.unshift({ url });
  }
}
return [{ json: { mensajes: buffer || textos.join('\n'), origen: buffer ? 'webhook' : 'conversacion', audios: audios.slice(-3) } }];

// Whisper necesita la extensión correcta en el nombre del archivo (las notas de WhatsApp llegan como .oga/.opus o sin extensión)
const EXT = { 'audio/ogg': 'ogg', 'application/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3',
  'audio/mp4': 'm4a', 'audio/x-m4a': 'm4a', 'audio/aac': 'm4a', 'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/webm': 'webm', 'audio/amr': 'amr' };
const out = [];
for (const item of $input.all()) {
  const b = item.binary?.data;
  if (!b) continue;
  const tipo = String(b.mimeType || '').split(';')[0].toLowerCase();
  let ext = EXT[tipo] || String(b.fileExtension || '').toLowerCase();
  if (!ext || ext === 'oga' || ext === 'opus' || ext === 'bin') ext = 'ogg';
  b.fileName = 'nota_de_voz.' + ext;
  b.fileExtension = ext;
  if (!tipo.startsWith('audio')) b.mimeType = ext === 'mp3' ? 'audio/mpeg' : 'audio/' + ext;
  out.push(item);
}
return out;

// Junta el texto del cliente con lo que dijo en sus notas de voz
const base = $('Mensaje del cliente').first().json;
const t = $input.all().map(i => String(i.json.text || '').trim()).filter(Boolean);
const partes = [base.mensajes, ...t.map(x => '(nota de voz) ' + x)].filter(Boolean);
if (!t.length && base.audios.length && !base.mensajes)
  partes.push('(El cliente mandó una nota de voz que no se pudo escuchar. Pídele amablemente que te lo escriba.)');
return [{ json: { ...base, mensajes: partes.join('\n'), transcripciones: t } }];

// ¿El cliente escribe por WhatsApp y viene de un anuncio de Meta?
// En WhatsApp Meta cobra las conversaciones que no vienen de un anuncio y las de anuncio pasadas 72h,
// así que en esos casos no contesta la IA: pasa a "Sin IA" para que lo atiendan por WhatsApp directo.
// Los mensajes siguientes al del anuncio no traen el ID: la tabla RS_ventana_meta recuerda que sí vino de anuncio.
const CFG = {"loc": "Jf5jBydZMO0fdMeo1d4O", "pipe": "RzAjsLsppuOq0T0yiVIf", "sinIA": "c46b8e24-8ae5-4659-89d5-261dd5c0adb9", "campo": "GM9ymO6oh29ObOCsgXSJ", "agencia": "periodismo"};
const AVISO = {
  verde: '🟢 Anuncio menos de 72h: contestar por GHL',
  rojo: '🔴 Anuncio más de 72h: contestar por WhatsApp directo',
  sin_anuncio: '⚪ No viene de anuncio: contestar por WhatsApp directo',
  azul: '🔵 Facebook / Instagram: sin costo, contestar por GHL',
};
const wh = $('Webhook').first().json.body || {};
let c = {};
try { c = $('GHL contacto (origen)').first().json.contact || {}; } catch (e) {}
let msgs = [];
try { msgs = $('GHL mensajes (texto)').first().json.messages?.messages || []; } catch (e) {}
// GHL los devuelve del más nuevo al más viejo
const entrantes = msgs.filter(m => m.direction === 'inbound' && !String(m.messageType || '').startsWith('TYPE_ACTIVITY'));
const tipo = String((entrantes[0] || {}).messageType || '');
const medios = [c.lastAttributionSource?.medium, wh.contact?.lastAttributionSource?.medium, c.attributionSource?.medium, wh.contact?.attributionSource?.medium]
  .map(v => String(v || '').toLowerCase());
const esWhatsApp = tipo ? tipo === 'TYPE_WHATSAPP' : (Number(wh.message?.type) === 19 || medios[0].startsWith('whatsapp') || medios[1].startsWith('whatsapp'));

const atribuciones = [c.lastAttributionSource, wh.contact?.lastAttributionSource, c.attributionSource, wh.contact?.attributionSource].filter(Boolean);
const las = atribuciones[0] || {};
const adId = atribuciones.map(a => a.ctwa_clid || a.adId).find(Boolean) || '';
const REFERIDO = /\*Headline:\*|Source URL:|https:\/\/fb\.me\//i;
const referido = entrantes.find(m => REFERIDO.test(m.body || ''));
const esAnuncio = !!adId || !!referido;
const clave = String(las.ctwa_clid || las.adId || adId || (referido ? 'ref-' + referido.id : ''));
// Inicio de la ventana: el mensaje que llegó desde el anuncio; si ya no está entre los últimos, la fecha de alta del contacto
const desde = referido?.dateAdded || c.dateAdded || new Date().toISOString();
const nombre = [c.firstName || wh.first_name, c.lastName].filter(Boolean).join(' ') || wh.full_name || c.phone || wh.phone || 'Lead sin nombre';
// Facebook e Instagram no tienen costo por mensaje: aviso azul (solo si aún no lo tiene)
const esFbIg = !esWhatsApp && (/FACEBOOK|INSTAGRAM/.test(tipo) || /facebook|instagram/.test(medios[0] || medios[1]));
const avisoActual = ((c.customFields || []).find(f => f.id === CFG.campo) || {}).value || '';
const ponerAzul = esFbIg && avisoActual !== AVISO.azul;
return [{ json: { ...CFG, canalTipo: tipo, contact_id: wh.contact_id, esWhatsApp, esAnuncio, esFbIg, ponerAzul, sinAnuncioWhatsApp: esWhatsApp && !esAnuncio,
  anuncioWhatsApp: esWhatsApp && esAnuncio, clave, desde, nombre, AVISO } }];
